def batches(values, size):
    if type(size) is not int or size<1: raise ValueError('size')
    output=[]
    batch=[]
    for value in values:
        batch.append(value)
        if len(batch)==size:
            output.append(batch)
            batch=[]
    if batch: output.append(batch)
    return output

