import posixpath
def normalize(value):
    if not value or value.startswith('/') or '\\' in value or '\x00' in value: raise ValueError('path')
    value=posixpath.normpath(value)
    if value in ('.','..') or value.startswith('../'): raise ValueError('path')
    return value

